=== src/main/java/hotel/reservations/PriceCalculator.java
     1	package hotel.reservations;
     2	
     3	import hotel.reservations.seasons.Season;
     4	import hotel.reservations.seasons.SeasonCalendar;
     5	import hotel.rooms.Room;
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	import java.util.Optional;
    10	
    11	/**
    12	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    13	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    14	 * (half-even) at every step.
    15	 */
    16	public final class PriceCalculator {
    17	
    18	    private static final SeasonCalendar SEASONS = new SeasonCalendar();
    19	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    20	
    21	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    22	        int nights = 0;
    23	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    24	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    25	            subtotal = subtotal.add(nightPrice(room, night));
    26	            nights++;
    27	        }
    28	        BigDecimal discount = switch (ratePlan) {
    29	            case STANDARD -> cents(BigDecimal.ZERO);
    30	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    31	        };
    32	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    33	    }
    34	
    35	    BigDecimal nightPrice(Room room, LocalDate night) {
    36	        BigDecimal nightlyRate = room.nightlyRate();
    37	        Optional<Season> season = SEASONS.seasonOf(night);
    38	        if (season.isPresent()) {
    39	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(season.get().surcharge())));
    40	        }
    41	        return cents(nightlyRate);
    42	    }
    43	
    44	    static boolean isHighSeason(LocalDate date) {
    45	        return SEASONS.seasonOf(date).isPresent();
    46	    }
    47	
    48	    static BigDecimal cents(BigDecimal value) {
    49	        return value.setScale(2, RoundingMode.HALF_EVEN);
    50	    }
    51	}
